using System;
using System.Linq;
using System.IO;
using System.Drawing;
using System.Windows.Forms;
using System.Reflection;
using System.Collections.Generic;

namespace Ara {
 public static class AdaptiveTests {
  static void Assert(bool yes,string message){if(!yes)throw new Exception(message);}
  static State New(){var s=State.New();GridEngine.Ensure(s,s.GetDay(DateTime.Today));return s;}
  static Day D(State s){return s.Days[0];}
  static CellBlock Meal(GridPlan p,string id){return p.Blocks.Find(x=>x.MealId==id);}
  static void Record(Day d,string id,DateTime time,int count=3){d.Records.Add(new CellBlock{Id="actual-"+id,Start=time,Count=count,Name=id,MealId=id,Category="식사",Score=2});}
  static void Consistent(GridPlan p){for(int i=1;i<p.Blocks.Count;i++)Assert(p.Blocks[i].Start>=p.Blocks[i-1].End,"overlap");}
  static GridPlan FirstDelay(State s,int minutes){Record(D(s),"b1",D(s).Wake.AddMinutes(30+minutes));return GridEngine.Build(s,D(s));}
  static IEnumerable<Control> Children(Control c){foreach(Control child in c.Controls){yield return child;foreach(var nested in Children(child))yield return nested;}}
  static void DeleteKey(MainForm f){var e=new KeyEventArgs(Keys.Delete);typeof(Timetable).GetMethod("OnKeyDown",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(f.Board,new object[]{e});Assert(e.Handled&&e.SuppressKeyPress,"Delete consumed");}
  public static void Run(Action<string,Action> check,string dir){
   check("adaptive: small delays spend waiting gap before dropping any activity",()=>{var s=New();var d=D(s);var p=FirstDelay(s,20);Assert(p.Blocks.Single(x=>x.Category=="존2").Start==d.Records[0].Start.AddMinutes(100),"front wait cut20 first");Assert(Meal(p,"b10")!=null&&p.Blocks.Single(x=>x.Category=="웨이트").Count==12&&p.Saved==20&&p.Overflow==0,"all activities retained");Assert(GridEngine.AsPlan(s,d,p).Target==d.Wake.AddMinutes(990),"bedtime unchanged");Consistent(p);});
   check("adaptive: 50-minute delay spends front thirty then shower-tail twenty",()=>{var s=New();var p=FirstDelay(s,50);Assert(p.Blocks.Single(x=>x.Category=="존2").Start==D(s).Records[0].Start.AddMinutes(90),"front reaches ninety-minute start floor");Assert(Meal(p,"b10")!=null&&p.Saved==50&&p.Overflow==0,"no meal dropped");Consistent(p);});
   check("adaptive: waiting floor also respects actual eating duration",()=>{var s=New();var d=D(s);Record(d,"b1",d.Wake.AddMinutes(90),9);var p=GridEngine.Build(s,d);Assert(p.Blocks.Single(x=>x.Category=="존2").Start>=d.Records[0].End,"never during actual eating");Assert(d.Records[0].Count==9&&GridEngine.Total(d)==18&&p.Overflow==0,"facts retained");Consistent(p);});
   check("adaptive: 90-minute delay spends gap then omits third meal with its prep",()=>{var s=New();var p=FirstDelay(s,90);Assert(Meal(p,"b10")==null&&!p.Blocks.Any(x=>x.PrepFor=="b10"),"third meal and prep omitted");Assert(p.Blocks.Single(x=>x.Category=="존2").Count==4&&p.Blocks.Single(x=>x.Category=="웨이트").Count==12&&p.Overflow==0,"zone/weights retained");Assert(p.Changes.FindIndex(x=>x.Contains("대기"))<p.Changes.FindIndex(x=>x.Contains("3끼니")&&x.Contains("제외")),"priority order");Consistent(p);});
   check("adaptive: omitting third meal leaves two hours free after eating second meal",()=>{var s=New();var p=FirstDelay(s,90);var weights=p.Blocks.Single(x=>x.Category=="웨이트");Assert(weights.Start==Meal(p,"b6").Start.AddMinutes(150),"weights from second meal");Assert(Meal(p,"b15").Start==weights.End.AddHours(1)&&Meal(p,"b16").Start==Meal(p,"b15").Start.AddHours(3),"later intervals preserved");Consistent(p);});
   check("adaptive: 270-minute delay uses yogurt while retaining zone2",()=>{var s=New();var p=FirstDelay(s,270);Assert(Meal(p,"b10")==null&&p.Blocks.Any(x=>x.Category=="존2")&&Meal(p,"b16")==null,"third and yogurt used before zone omission");Assert(p.Blocks.Any(x=>x.TemplateId=="b5")&&p.Blocks.Single(x=>x.Category=="웨이트").Count==12&&p.Overflow==0,"shower and weights retained");Assert(!p.Changes.Any(x=>x.Contains("존2")&&x.Contains("제외")),"zone not removed for zero benefit");Consistent(p);});
   check("adaptive: yogurt is omitted before shortening weights",()=>{var s=New();var p=FirstDelay(s,300);Assert(p.Blocks.Single(x=>x.Category=="웨이트").Count==12&&p.Overflow==0&&p.Saved==300,"weights retained");Assert(Meal(p,"b16")==null,"yogurt removed before weights");Assert(p.Blocks.Any(x=>x.Category=="존2"),"yogurt used before removing zone");Consistent(p);});
   check("adaptive: exhaustion preserves minimum weights and reports unavoidable overrun",()=>{var s=New();var p=FirstDelay(s,600);Assert(p.Blocks.Single(x=>x.Category=="웨이트").Count==3&&p.Overflow==210&&p.Saved==390,"390 recovered, 210 left with post-meal rest");Assert(Meal(p,"b16")==null&&D(s).Records.Single().Start==D(s).Wake.AddMinutes(630),"yogurt omitted and facts fixed");Consistent(p);});
   check("adaptive: recorded third meal and past zone2 are never automatically erased",()=>{var s=New();var d=D(s);Record(d,"b10",d.Wake.AddMinutes(570));var p=GridEngine.Build(s,d);Assert(Meal(p,"b10").Start==d.Records[0].Start&&p.Blocks.Single(x=>x.Category=="존2").Count==4,"history retained");Assert(p.Blocks.Single(x=>x.Category=="웨이트").Count==9&&Meal(p,"b16")==null&&p.Overflow==0,"yogurt used before weight shortening to protect rest");Consistent(p);});
   check("adaptive: actual zone2 anchor recovers already-used waiting buffer",()=>{var s=New();var d=D(s);Record(d,"b1",d.Wake.AddMinutes(50));d.Records.Add(new CellBlock{Id="zone",Start=d.Wake.AddMinutes(150),Count=4,Name="존2",Category="존2",TemplateId="b4",Score=3});var p=GridEngine.Build(s,d);Assert(p.Blocks.Single(x=>x.Category=="존2").Start==d.Records[1].Start&&Meal(p,"b10")!=null&&p.Overflow==0,"performed zone anchored, no meal omitted");Assert(GridEngine.Total(d)==18,"scores retained");Consistent(p);});
   check("adaptive: after weights only yogurt is omitted and bedtime stays fixed",()=>{var s=New();var d=D(s);Record(d,"b15",d.Wake.AddMinutes(930));var p=GridEngine.Build(s,d);Assert(Meal(p,"b16")==null&&!p.Blocks.Any(x=>x.PrepFor=="b16"),"yogurt omitted");Assert(Meal(p,"b10")!=null&&p.Blocks.Single(x=>x.Category=="존2").Count==4&&p.Blocks.Single(x=>x.Category=="웨이트").Count==12,"past schedule unchanged");Assert(p.Overflow==90&&GridEngine.AsPlan(s,d,p).Target==d.Wake.AddMinutes(990)&&Adaptive.EstimatedSleep(s,d,p)==Adaptive.Target(s,d)&&Adaptive.RequiredFinish(s,d,p)==d.Records[0].End.AddHours(2),"fixed target with honest ninety-minute overrun");Consistent(p);});
   check("adaptive: actual weight duration drives fourth meal from weight end",()=>{var s=New();var d=D(s);d.Records.Add(new CellBlock{Id="weight-a",Start=d.Wake.AddMinutes(570),Count=9,Category="웨이트",TemplateId="b8",Score=1});d.Records.Add(new CellBlock{Id="weight-b",Start=d.Wake.AddMinutes(660),Count=9,Category="웨이트",TemplateId="b8",Score=2});var p=GridEngine.Build(s,d);var weight=p.Blocks.Single(x=>x.Category=="웨이트");Assert(weight.Count==18&&weight.Start==d.Records[0].Start&&Meal(p,"b15").Start==weight.End.AddHours(1),"contiguous actual weights aggregated");Assert(Meal(p,"b16")==null&&p.Overflow==0&&GridEngine.Total(d)==27,"only yogurt omitted, facts retained");Consistent(p);});
   check("adaptive: already-eaten yogurt cannot be omitted to fabricate on-time sleep",()=>{var s=New();var d=D(s);Record(d,"b15",d.Wake.AddMinutes(870));Record(d,"b16",d.Wake.AddMinutes(1050));var p=GridEngine.Build(s,d);Assert(Meal(p,"b16").Start==d.Records[1].Start&&p.Overflow==90&&d.Records.Count==2,"completed yogurt retained with overrun");Consistent(p);});
   check("adaptive: clearing delay restores omitted plans from unchanged baseline",()=>{var s=New();var original=D(s).GridBase.Select(x=>x.Id+":"+x.Start.ToString("o")+":"+x.Count).ToArray();FirstDelay(s,300);D(s).Records.Clear();var p=GridEngine.Build(s,D(s));Assert(Meal(p,"b10")!=null&&p.Blocks.Single(x=>x.Category=="존2").Count==4&&p.Blocks.Single(x=>x.Category=="웨이트").Count==12,"plans restored");Assert(original.SequenceEqual(D(s).GridBase.Select(x=>x.Id+":"+x.Start.ToString("o")+":"+x.Count)),"baseline never mutated");});
   check("delete: real Delete handler removes clicked actual block and undo restores it",()=>{var s=New();var d=D(s);d.Records.Add(new CellBlock{Id="work",Start=d.Wake.AddHours(2),Count=12,Category="작업",Score=3});using(var f=new MainForm(new Store(Path.Combine(dir,"delete-actual.json")),s,true)){f.Show();Application.DoEvents();f.Board.SimulateDrag(1,f.Board.Index(d.Wake.AddHours(2)),f.Board.Index(d.Wake.AddHours(2)),false);Assert(f.Board.Selection.Count==12,"whole block selected");DeleteKey(f);Assert(f.Day.Records.Count==0&&GridEngine.Total(f.Day)==0,"block deleted");Children(f).OfType<Button>().Single(x=>x.Text=="되돌리기").PerformClick();Assert(f.Day.Records.Single().Id=="work"&&GridEngine.Total(f.Day)==36,"undo preserves score");f.Quit();}});
   check("delete: upper meal deletion also removes its prep without deleting actual facts",()=>{var s=New();var d=D(s);Record(d,"b1",d.Wake.AddMinutes(30));using(var f=new MainForm(new Store(Path.Combine(dir,"delete-plan.json")),s,true)){f.Show();Application.DoEvents();var third=Meal(f.GridPlan,"b10");int cell=f.Board.Index(third.Start);f.Board.SimulateDrag(0,cell,cell,false);DeleteKey(f);Assert(!f.Day.GridBase.Any(x=>x.MealId=="b10"||x.PrepFor=="b10")&&f.Day.Records.Count==1,"meal/prep only deleted");Assert(Meal(f.GridPlan,"b16")!=null&&f.GridPlan.Blocks.Single(x=>x.Category=="웨이트").Count==12,"other upper blocks retained");f.Quit();}});
   check("delete: Delete works while category menu is open",()=>{var s=New();var d=D(s);d.Records.Add(new CellBlock{Id="a",Start=d.Wake.AddHours(2),Count=6,Category="학습",Score=2});using(var f=new MainForm(new Store(Path.Combine(dir,"delete-menu.json")),s,true)){f.Show();Application.DoEvents();f.Board.SetSelection(new CellSelection{Lane=1,First=f.Board.Index(d.Records[0].Start),Last=f.Board.Index(d.Records[0].End)-1});f.ShowCategories();var e=new KeyEventArgs(Keys.Delete);typeof(ContextMenuStrip).GetMethod("OnKeyDown",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(f.CurrentCategoryMenu,new object[]{e});Application.DoEvents();Assert(e.Handled&&f.Day.Records.Count==0&&!f.CurrentCategoryMenu.Visible,"menu Delete closes and deletes");f.Quit();}});
   check("adaptive: delay sweep always respects waiting floor and nonoverlap",()=>{for(int delay=0;delay<=500;delay+=10){var s=New();var p=FirstDelay(s,delay);var zone=p.Blocks.Find(x=>x.Category=="존2");if(zone!=null)Assert(zone.Start>=D(s).Records[0].End.AddMinutes(60),"one hour after actual meal end");Assert(p.Blocks.Single(x=>x.Category=="웨이트").Count>=3&&GridEngine.AsPlan(s,D(s),p).Target==D(s).Wake.AddMinutes(990),"minimum and fixed target");Consistent(p);}});
  }
 }
}

